"""Route simulation: fuel burn between stops and pickup weight accrual."""

FUEL_BURN_RATE_L_PER_KM = 0.38
COMPACTION_RATIO = 0.65

AVG_BIN_FILL_FRACTION = {
    "empty": 0.1,
    "half": 0.5,
    "full": 0.9,
    "overflow": 1.15,
}

BIN_CAPACITY_KG = {
    "residential": 45,
    "commercial": 240,
    "dumpster": 900,
}


def build_route(truck, stops):
    leg_log = []
    for stop in stops:
        distance_km = stop["distance_from_prev_km"]
        truck.consume_fuel(distance_km * FUEL_BURN_RATE_L_PER_KM)

        pickup_kg = estimate_pickup_weight(stop)
        truck.add_payload(pickup_kg)

        if stop.get("compactable", True):
            truck.compact_load(COMPACTION_RATIO)

        leg_log.append({
            "stop_id": stop["stop_id"],
            "pickup_kg": pickup_kg,
            "gross_weight_kg": truck.gross_weight_kg,
            "fuel_liters": truck.fuel_liters,
        })
    return leg_log


def estimate_pickup_weight(stop):
    fill_fraction = AVG_BIN_FILL_FRACTION[stop["fill_level"]]
    capacity_kg = BIN_CAPACITY_KG[stop["bin_type"]]
    return round(fill_fraction * capacity_kg, 1)

"""Daily route planning and weight-compliance check for the collection fleet."""

from fleet import FleetTruck
from routing import build_route

ROAD_WEIGHT_LIMIT_KG = 11500


def plan_daily_route(stops, truck_id="T-14"):
    truck = FleetTruck(truck_id=truck_id, curb_weight_kg=6800, fuel_liters=180)
    leg_log = build_route(truck, stops)

    overweight_legs = [
        leg for leg in leg_log if leg["gross_weight_kg"] > ROAD_WEIGHT_LIMIT_KG
    ]
    if overweight_legs:
        return {
            "truck_id": truck_id,
            "status": "reroute_required",
            "flagged_legs": overweight_legs,
        }
    return {"truck_id": truck_id, "status": "cleared", "flagged_legs": []}


def summarize_route(result):
    if result["status"] == "cleared":
        return f"Truck {result['truck_id']} cleared all legs under the bridge weight limit."
    flagged = ", ".join(str(leg["stop_id"]) for leg in result["flagged_legs"])
    return f"Truck {result['truck_id']} needs reroute -- overweight near stops: {flagged}"
